FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 150: probes: a split cylinder's edges, under-constrained sketches settling. Generated by tools/fixtures/gen-batch-150.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

// Each edge's curve type, its ends and its direction at the start, in millimetres, rounded to 1e-6; sorted, as the
// kernels list a split's edges in their own orders.
function edgeProbe(context is Context, edges is Query) returns array
{
    const r = function(v) { return [round(v[0] / millimeter * 1e6) / 1e6, round(v[1] / millimeter * 1e6) / 1e6, round(v[2] / millimeter * 1e6) / 1e6]; };
    var out = [];
    for (var e in evaluateQuery(context, edges))
    {
        const a = evEdgeTangentLine(context, { "edge" : e, "parameter" : 0 });
        const b = evEdgeTangentLine(context, { "edge" : e, "parameter" : 1 });
        const d = a.direction;
        const c = evCurveDefinition(context, { "edge" : e });
        const s = r(a.origin);
        out = append(out, [(c is Line ? 1e6 : 0) + s[2] * 100 + s[1], [c is Line ? "line" : (c is Circle ? "circle" : (c is Ellipse ? "ellipse" : "other")), s, r(b.origin), [round(d[0] * 1e6) / 1e6, round(d[1] * 1e6) / 1e6, round(d[2] * 1e6) / 1e6]]]);
    }
    return mapArray(sort(out, function(a, b) { return a[0] - b[0]; }), function(x) { return x[1]; });
}

// A sketch's solved curves: lines as their ends, circles as centre and radius; sorted, as Onshape lists curves held
// to each other in the order the sketch made them and the engine doesn't (batch 136 c015).
function sketchProbe(context is Context, sketchId is Id) returns array
{
    var out = [];
    for (var e in evaluateQuery(context, qOwnedByBody(qBodyType(qCreatedBy(sketchId, EntityType.BODY), BodyType.WIRE), EntityType.EDGE)))
    {
        const c = evCurveDefinition(context, { "edge" : e });
        const a = evEdgeTangentLine(context, { "edge" : e, "parameter" : 0 }).origin;
        const b = evEdgeTangentLine(context, { "edge" : e, "parameter" : 1 }).origin;
        const r = function(x) { return round(x / millimeter * 1e6) / 1e6; };
        if (c is Line)
            out = append(out, [1e9 + r(a[0]) * 1000 + r(a[1]), ["line", r(a[0]), r(a[1]), r(b[0]), r(b[1])]]);
        else if (c is Circle)
            out = append(out, [r(c.coordSystem.origin[0]) * 1000 + r(c.coordSystem.origin[1]), ["circle", r(c.coordSystem.origin[0]), r(c.coordSystem.origin[1]), r(c.radius)]]);
    }
    return mapArray(sort(out, function(a, b) { return a[0] - b[0]; }), function(x) { return x[1]; });
}

// split: a cylinder (radius 10, 30 tall) with its side split by an 8 × 10 rectangle projected from beside it: the split's edges' ends and directions
export function c001(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
    const cut = newSketchOnPlane(context, id + "cut", { "sketchPlane" : plane(vector(15, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skRectangle(cut, "rect1", { "firstCorner" : vector(-4, 10) * millimeter, "secondCorner" : vector(4, 20) * millimeter });
    skSolve(cut);
    splitPart(context, id + "split1", { "splitType" : SplitType.FACE, "faceTargets" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(10, 0, 15) * millimeter), "faceTools" : qOwnedByBody(qBodyType(qCreatedBy(id + "cut", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "projectionType" : ProjectionType.NORMAL_TO_TARGET });
    return { "edges" : edgeProbe(context, qCreatedBy(id + "split1", EntityType.EDGE)) };
}

// sketch: a circle (radius 10) and then a line drawn 0.5 above its top, held tangent
export function c002(context is Context, id is Id)
{
    const s = newSketchOnPlane(context, id + "s", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skLineSegment(s, "l1", { "start" : vector(-15, 10.5) * millimeter, "end" : vector(15, 10.5) * millimeter });
    skConstraint(s, "t1", { "constraintType" : ConstraintType.TANGENT, "localFirst" : "l1", "localSecond" : "c1" });
    skSolve(s);
    return { "curves" : sketchProbe(context, id + "s") };
}

